import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第42章 卷末","description":"","frontmatter":{},"headers":[],"relativePath":"第42章_卷末.md","filePath":"第42章_卷末.md"}'),r={name:"第42章_卷末.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第42章-卷末" tabindex="-1">第二卷 回潮 · 第42章 卷末 <a class="header-anchor" href="#第二卷-回潮-·-第42章-卷末" aria-label="Permalink to &quot;第二卷 回潮 · 第42章 卷末&quot;">​</a></h1><p>高一结束那几天，蝉鸣像是被暑气煮透了，贴在窗外嗡嗡响。</p><p>我坐在宿舍的书桌前，风扇转得很慢，吹出来的风也是热的。桌上摊着带回来的卷子，纸角被汗洇得发软，字迹有点花。我盯着那些红圈看了很久，又把卷子翻过去，不想再看。</p><p>顾远在上铺翻身，床板咯吱一声。</p><p>“睡不着？”他探出头问我。</p><p>我点点头，又摇摇头，喉咙发干。</p><p>“都考完了，想也没用。”他说，“睡吧，明天还要搬东西。”</p><p>我说好，可闭上眼，脑子里还是吊扇声和笔尖划纸的沙沙声。</p><p>走廊里有人拖着行李箱走过，轮子碾过地板，发出闷闷的响。有人在笑，有人在喊名字，整个楼都像泡在离别的汽水里，又酸又胀。</p><p>我起身去洗了把脸。水很凉，贴在脸上，薄荷水似的清醒了一下。镜子里的我眼睛有点红，下巴冒出一点青茬，看起来蔫蔫的。我把毛巾用热水烫了一下再拧干，热毛巾敷在脸上，一热一凉，鼻尖闻到的是肥皂的清香混着水汽的闷，让人稍微醒过来。</p><p>回到座位，我摸出抽屉里的玻璃罐，只剩底下薄薄一层。江苒叠的星星角很挺，灯下透着淡淡的光。我把罐子捧在手心轻晃，星星碰到玻璃壁发出细碎的轻响，再把罐盖拧开，挑出一颗在指尖转一圈，又小心放回去，盖紧时指腹硌到星角，轻疼一下，心倒安稳了些。</p><p>手机在桌上震了一下，我的心跟着跳了一下。</p><p>是家里的电话。我盯着屏幕看了几秒，才接起来。</p><p>“喂。”</p><p>那头有点吵，像是风扇和电视混在一起的声音。母亲问我什么时候回家，票买好没有。我说买好了，就这几天。</p><p>她顿了顿，问考得怎么样。</p><p>我握着手机，指尖发凉。窗外的蝉叫得更大了，吵得我太阳穴突突跳。我说，还行，有几门没发挥好。</p><p>她说没事，尽力就好。可语气里的停顿，比直接问更让人难受。</p><p>挂了电话，我在椅子上坐了很久。汗从后背渗出来，黏在椅背上。风扇依旧慢慢转，吹不动这屋里的闷。</p><p>陈默从外面回来，抱着一摞书，脸上全是汗。</p><p>“你也失眠啊。”他把书放下，抽出一瓶橘子汽水递给我，“冰的，刚从小卖部抢的。”</p><p>我接过来，瓶身凉凉的，贴在手心很舒服。起盖的时候，气顶出来，发出很轻的一声，橘子味一下子漫开。</p><p>“谢谢。”我说。</p><p>他坐下来，仰头喝了一大口，长长出了口气，说秦浩暑假要去亲戚家住，他们也要出一趟远门。</p><p>我点点头，不知道说什么。离别这件事，越是临近，越是说不出像样的话。</p><p>“秦浩还在操场跑圈，何晓给他留了海盐糖。”他笑了笑，又补了一句：“你别老闷着，有话就说出来，别都憋在纸上。”这话不带新事，只是把我写纸条的习惯点了一下，我听了点点头，想起在连廊里江苒也说过类似的话，那时我也是点头快，改得慢。</p><p>我跟着笑了笑，嘴里的汽水泛着甜，又有点涩。</p><p>夜深了，宿舍陆续熄灯。顾远的呼噜声很快响起来，陈默也爬上床，翻了两页书就睡了。我躺在床上，听着风扇的嗡鸣，数着自己的心跳，怎么都睡不着。那是我第一次真正失眠，眼睛睁着看天花板，脑子里全是卷子上红圈和江苒电话里的呼吸，一热一凉来回拉扯。</p><p>我摸出枕头下那颗没折完的纸星星。那是宋阿婆塞的，叶老师说累的时候看看窗外能松快些。我捏在手里，纸角软软的，倒让人踏实一点。</p><p>不知过了多久，我走到阳台。夜风带着食堂的油烟味，校园很静，只有楼梯间还亮着一盏灯。</p><p>我想起高一刚来的时候，也是站在类似的阳台。江苒在楼下喊我的名字，举着纸星星说，今晚的云像不像海。那时的风里带着枇杷的甜香。</p><p>手机又震了一下。这次是江苒。</p><p>我深吸一口气，接起来。</p><p>“还没睡？”她的声音轻轻的，带着一点鼻音，像是也熬着。</p><p>“嗯，睡不着。”我说。</p><p>她笑了，那头传来很轻的铃铛声，叮的一下，像星星掉进水里。</p><p>“巧了，我也睡不着。”她说，“刚才数星星，数到一半数乱了。”</p><p>我靠在栏杆上，夜风把汗吹干，凉凉的。</p><p>“江苒。”我说，“这次我可能考得很糟。”高二开学这场考，我心里已经有了数，话说出来反而轻了一点。</p><p>她那边安静了几秒，只有很轻的呼吸声。</p><p>“我知道你尽力了。”她说，“考场上那个风扇声，我也听到了，吵得我笔都拿不稳。”</p><p>我鼻子有点酸，赶紧仰起头，看着天。雾山市的夜空看不到星，只有云很低很低地压着，透着城市的光，泛着暗红。</p><p>“别怕。”她说，“高一嘛，只是回潮前的退潮。你看海的时候，浪退下去，是为了涨得更高。”</p><p>她的声音很亮，像往常一样，带着让人安心的力量。可我还是听出一丝不一样，像是藏着什么，没说出口。</p><p>“你暑假怎么过？”我问。</p><p>她顿了一下，说可能要陪家里人出去一趟，地方有点远，信可能寄不到，纸星星也要停一阵子了。</p><p>我的心一下子沉下去，手指收紧，栏杆的铁锈味沾在手上。</p><p>“停多久？”我问，声音有点哑。</p><p>“不知道。”她轻声说，“也许很快，也许要等开学。沈聿，罐子里的星星，你省着点数。”</p><p>风忽然停了，阳台闷得让人喘不过气。我听见自己的心跳，一下一下，敲在耳膜上。电话贴在耳边，她的呼吸很轻，可我忽然觉得这通电话也开始让人焦虑，像揣着一颗不敢摇晃的星星，怕晃散了光。</p><p>“好。”我说，“我等你。”</p><p>她笑了，铃铛又响了一下。</p><p>“沈聿，你知道吗，我有点怕。”她忽然说，“怕高二分班，怕走散，怕我们回不到现在。”</p><p>我愣住了。这是她第一次在我面前说怕。印象里的江苒，总是明亮的，举着纸星星跑在前面，好像什么都不怕。</p><p>“不会的。”我说得很慢，每一个字都像从胸口掏出来，“你去哪，我就把纸条写到哪。星星停更，我就自己叠，叠到你回来数。”</p><p>她在那头轻轻吸了吸鼻子，又笑了。</p><p>“那说好了。”她说，“高二见。到时候，南雾中学的风，肯定比现在凉。”</p><p>“高二见。”我说。</p><p>挂了电话，我在阳台站到腿发麻。远处一声火车鸣笛，夜气里混着薄荷的凉，一点点沉进肺里。</p><p>回到屋里，我把玻璃罐抱到桌上，倒出一颗星星，放在掌心。灯光下，星星的折痕清晰又温柔，像她说话时的眉眼。</p><p>我找出纸学着她的样子折，折到天色发白。纸条先压平再打结，尾巴缠紧，角顶鼓，每一步都跟着她的手势来，折坏一颗就捡起重来，指尖沾着纸粉，桌上慢慢多出几颗歪歪的星星。</p><p>顾远醒来，看到桌上多出的几颗丑星星，乐了。</p><p>“呦，沈聿开窍了。”他说，“叠得虽丑，心意到了。”</p><p>我笑了笑，把星星放进罐子，和她的放在一起。丑的和好看的挨着，倒也和谐。</p><p>行李收好，旧磁带包在衣服中间，海盐糖剩了两颗，书签夹在书里。罐子抱在怀里，像抱着整个高一。</p><p>走出宿舍楼的时候，阳光晃眼。林小满在楼下等，手里拿着枇杷，分给大家。酸甜的汁水在嘴里爆开，暑气好像都轻了一点。</p><p>叶老师站在树下，笑着和我们挥手，说高二见，记得写信。</p><p>我点点头，喉咙发紧，说不出话，只用力挥了挥手。</p><p>回头看，教学楼安静地立在蝉鸣里，窗玻璃反射着白光，像一片晃动的海。而我知道，真正的潮，还在高二等着我们。那封没写完的纸条，那罐没数完的星星，那个没说出口的约定，都被暑气封存，等秋风一起，就要漫上来了。</p>',69)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
